solutionCode:
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y }
}

impl Ponto {
    pub fn dobro_da_area(&self) -> i32 {
        self.x * self.y * 2
    }
}

testsCode:
use desafio::ponto_de;

#[test]
fn testa_o_dobro_da_area_do_dois_por_tres() {
    assert_eq!(ponto_de(2, 3).dobro_da_area(), 12);
}

#[test]
fn testa_o_dobro_da_area_do_um_por_um() {
    assert_eq!(ponto_de(1, 1).dobro_da_area(), 2);
}

#[test]
fn testa_o_dobro_da_area_do_zero_por_cinco() {
    assert_eq!(ponto_de(0, 5).dobro_da_area(), 0);
}
